// src/pages/CalendarPage.js

import React, { useState } from 'react';
import Calendar from 'react-calendar';
import ReviewModal from '../components/ReviewModal';
import 'react-calendar/dist/Calendar.css'; // react-calendar 기본 CSS
import '../Calendar.css'; // 커스텀 CSS 파일

function CalendarPage() {
  const [date, setDate] = useState(new Date());
  const [reviews, setReviews] = useState({}); // { "YYYY-MM-DD": { ...review } }
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleDateClick = (clickedDate) => {
    setDate(clickedDate);
    setIsModalOpen(true);
  };

  const handleSaveReview = (reviewData) => {
    const dateKey = reviewData.date.toISOString().split('T')[0];
    setReviews(prevReviews => ({
      ...prevReviews,
      [dateKey]: reviewData,
    }));
  };

  // 캘린더의 각 날짜 칸에 콘텐츠를 렌더링하는 함수
  const tileContent = ({ date, view }) => {
    if (view === 'month') {
      const dateKey = date.toISOString().split('T')[0];
      const review = reviews[dateKey];
      if (review && review.posterPath) {
        return (
          <div className="calendar-poster-wrapper">
            <img src={review.posterPath} alt="review poster" className="calendar-poster" />
          </div>
        );
      }
    }
    return null;
  };

  const selectedDateKey = date.toISOString().split('T')[0];

  return (
    <div className="calendar-page-container">
      <h1 className="page-title">나의 관람 캘린더</h1>
      <Calendar
        onChange={setDate}
        value={date}
        onClickDay={handleDateClick}
        tileContent={tileContent}
        formatDay={(locale, date) => date.getDate()} // '일' 글자 제거
        calendarType="US" // 월요일 시작
      />
      <ReviewModal
        isOpen={isModalOpen}
        onRequestClose={() => setIsModalOpen(false)}
        date={date}
        existingReview={reviews[selectedDateKey]}
        onSave={handleSaveReview}
      />
    </div>
  );
}

export default CalendarPage;
